// rle: run-length encoding of 8 MiB of generated bytes with runs of 1 to
// 16, as (length, byte) pairs with lengths up to 255, then decoded and
// compared. Prints the encoded size, the sum of the encoded bytes and 1
// when the decoded bytes equal the original.

fn mix(b: i64) -> i64 {
    b * 2654435761 >> 13
}

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n)
        .map(|i| {
            let b = i / 16;
            let v = 8 * (b & 1) + (mix(b) & 3);
            (if i % 16 < mix(b + 7) % 16 + 1 { v } else { v + 4 }) as u8
        })
        .collect();
    let mut enc = Vec::with_capacity(data.len() / 4);
    let mut i = 0;
    while i < data.len() {
        let mut j = i;
        while j < data.len() && data[j] == data[i] && j - i < 255 {
            j += 1;
        }
        enc.push((j - i) as u8);
        enc.push(data[i]);
        i = j;
    }
    let mut dec = Vec::with_capacity(data.len());
    for p in enc.chunks_exact(2) {
        dec.extend(std::iter::repeat_n(p[1], p[0] as usize));
    }
    let sum: i64 = enc.iter().map(|&b| b as i64).sum();
    println!("{} {} {}", enc.len(), sum, (dec == data) as i32);
}
